<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center" style="margin-top:28px;margin-bottom:24px">トップページで選んだ4つの重視ポイントに、上の表を当てはめたものです。</p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#14264a"},"typography":{"fontSize":"20px","lineHeight":"1.5"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<h3 class="has-text-color" style="color:#14264a;font-size:20px;line-height:1.5;margin-top:0px;margin-bottom:0px"><span style="font-size:13px;letter-spacing:.08em;color:#6e5312;display:block;margin-bottom:4px;">CASE 1</span>年会費を払いたくない</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:16px;line-height:1.9">「年会費は1円も払いたくない」という人です。ここは Aカードと Dカードの争いで、どちらも永年無料。<strong>差はポイントの使い道で、Dカードのほうが特約店の還元率が高め。</strong>年に数回しかカードを使わないなら、還元率の差はほとんど気にしなくてかまいません。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-company-2 {"maxWidth":1040,"spFullDt":true,"dtWidthClass":"dt_width_l","dtBackgroundColor":"#f5efe2","dtTextColor":"#14264a","ddTextColor":"#1f2733","borderColor":"#ddd3ba"} -->
<div class="wp-block-wdl-lw-company-2 font_size_m" style="border-color:#ddd3ba"><dl class="sp_clm_1" style="border-color:#ddd3ba;max-width:1040px;line-height:1.6"><div class="company-profile-item font_size_m dt_width_l" style="border-color:#ddd3ba"><dt style="background-color:#f5efe2;color:#14264a;line-height:1.6" data-lw_font_set="">年会費が無料</dt><dd style="color:#1f2733;line-height:1.6" data-lw_font_set="">Aカード・Dカード（条件なしで永年無料）</dd></div><div class="company-profile-item font_size_m dt_width_l" style="border-color:#ddd3ba"><dt style="background-color:#f5efe2;color:#14264a;line-height:1.6" data-lw_font_set="">気をつける点</dt><dd style="color:#1f2733;line-height:1.6" data-lw_font_set="">無料カードは基本還元率が0.5%と控えめです</dd></div><div class="company-profile-item font_size_m dt_width_l" style="border-color:#ddd3ba"><dt style="background-color:#f5efe2;color:#14264a;line-height:1.6" data-lw_font_set="">迷ったら</dt><dd style="color:#1f2733;line-height:1.6" data-lw_font_set="">特約店をよく使うなら Dカードのほうが得しやすい</dd></div></dl></div>
<!-- /wp:wdl/lw-company-2 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#14264a"},"typography":{"fontSize":"20px","lineHeight":"1.5"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<h3 class="has-text-color" style="color:#14264a;font-size:20px;line-height:1.5;margin-top:0px;margin-bottom:0px"><span style="font-size:13px;letter-spacing:.08em;color:#6e5312;display:block;margin-bottom:4px;">CASE 2</span>ポイントを貯めたい</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:16px;line-height:1.9">日常の買い物でポイントを貯めたい人です。特約店の還元率帯は <strong>Cカードが最大3.0%で最も高く</strong>、その代わり年会費が1,375円かかります。特約店をよく使わないなら、年会費の元が取れないことがあります。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-company-2 {"maxWidth":1040,"spFullDt":true,"dtWidthClass":"dt_width_l","dtBackgroundColor":"#f5efe2","dtTextColor":"#14264a","ddTextColor":"#1f2733","borderColor":"#ddd3ba"} -->
<div class="wp-block-wdl-lw-company-2 font_size_m" style="border-color:#ddd3ba"><dl class="sp_clm_1" style="border-color:#ddd3ba;max-width:1040px;line-height:1.6"><div class="company-profile-item font_size_m dt_width_l" style="border-color:#ddd3ba"><dt style="background-color:#f5efe2;color:#14264a;line-height:1.6" data-lw_font_set="">還元率が高い</dt><dd style="color:#1f2733;line-height:1.6" data-lw_font_set="">Cカード（特約店で最大3.0%・Bカード2.0%）</dd></div><div class="company-profile-item font_size_m dt_width_l" style="border-color:#ddd3ba"><dt style="background-color:#f5efe2;color:#14264a;line-height:1.6" data-lw_font_set="">年会費とのバランス</dt><dd style="color:#1f2733;line-height:1.6" data-lw_font_set="">月2万円以上を特約店で使うなら元が取れます</dd></div><div class="company-profile-item font_size_m dt_width_l" style="border-color:#ddd3ba"><dt style="background-color:#f5efe2;color:#14264a;line-height:1.6" data-lw_font_set="">気をつける点</dt><dd style="color:#1f2733;line-height:1.6" data-lw_font_set="">特約店以外での還元率はどのカードも1.0%前後です</dd></div></dl></div>
<!-- /wp:wdl/lw-company-2 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#14264a"},"typography":{"fontSize":"20px","lineHeight":"1.5"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<h3 class="has-text-color" style="color:#14264a;font-size:20px;line-height:1.5;margin-top:0px;margin-bottom:0px"><span style="font-size:13px;letter-spacing:.08em;color:#6e5312;display:block;margin-bottom:4px;">CASE 3</span>旅行・出張が多い</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:16px;line-height:1.9">出張や旅行が多い人です。<strong>空港ラウンジと旅行保険が無料で付くのはBカードだけ</strong>で、年会費11,000円はかかりますが、年に数回でも空港ラウンジを使うなら元が取れる計算です。Eカードもラウンジは使えますが有料（1回1,100円）です。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:16px;line-height:2;margin-top:0px;margin-bottom:0px">・年に3回以上旅行する … Bカード（ラウンジ無料・保険自動付帯）<br>・年に1〜2回程度 … Eカード（ラウンジ有料だが年会費が安い）<br>・旅行はほとんどしない … ラウンジ特典は不要、還元率だけで選ぶ</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#14264a"},"typography":{"fontSize":"20px","lineHeight":"1.5"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<h3 class="has-text-color" style="color:#14264a;font-size:20px;line-height:1.5;margin-top:0px;margin-bottom:0px"><span style="font-size:13px;letter-spacing:.08em;color:#6e5312;display:block;margin-bottom:4px;">CASE 4</span>はじめての1枚が欲しい</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:16px;line-height:1.9">学生・新社会人で初めて持つ人です。<strong>審査の通りやすさは年収より「他社での延滞歴の有無」に左右されます。</strong>最初の1枚は年会費無料のカードから始めて、使い方に慣れてから増やすほうが安全です。</p>
